{% extends "base.html" %}

{% block title %}トップページ{% endblock %}

{% block content %}
    <!-- メインコンテンツ -->
    <div class="container py-5">
      <h1 class="mb-4 text-center">学校レポート一覧</h1>

      <!-- 🔍 インクリメンタル検索バー -->
      <div class="mb-4">
        <input type="text" id="searchInput" class="form-control form-control-lg" placeholder="学校名で検索...">
      </div>

      {% if schools %}
        <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4" id="schoolList">
          {% for school in schools %}
          <div class="col school-card">
            <div class="card shadow-sm h-100">
              <div class="card-body">
                <h5 class="card-title">{{ school.name }}</h5>
              </div>
              {% if school.reports %}
              <ul class="list-group list-group-flush">
                {% for report in school.reports %}
                <li class="list-group-item d-flex justify-content-between align-items-center">
                  {{ report.subject }} 過去問分析レポート
                  <a href="{{ url_for('download_file', filename=report.pdf_filename) }}" class="btn btn-sm btn-outline-primary">
                    <i class="fas fa-file-pdf me-2"></i>ダウンロード
                  </a>
                </li>
                {% endfor %}
              </ul>
              {% endif %}
            </div>
          </div>
          {% endfor %}
        </div>
      {% else %}
        <div class="alert alert-info text-center">
          まだレポートがありません。
        </div>
      {% endif %}
    </div>

    <!-- Bootstrap JS -->
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>

    <!-- 🔍 インクリメンタル検索用スクリプト -->
    <script>
      document.getElementById("searchInput").addEventListener("input", function () {
        let filter = this.value.toLowerCase();
        let cards = document.querySelectorAll("#schoolList .school-card");

        cards.forEach(card => {
          let title = card.querySelector(".card-title").textContent.toLowerCase();
          if (title.includes(filter)) {
            card.style.display = "";
          } else {
            card.style.display = "none";
          }
        });
      });
    </script>
{% endblock %}


