          <div class="row row-cols-1 g-4" id="schoolsList">
            {% for school in schools %}
            <div class="col school-item">
              <div class="card shadow-sm h-100">
                <div class="card-body">
                  <div class="row align-items-center g-2">
                    <div class="col-12 col-md-auto flex-grow-1">
                      <h5 class="card-title mb-0">{{ school.name }}</h5>
                    </div>
                    {% if school.reports %}
                      <div class="col-12 col-md-auto">
                        <div class="d-flex flex-wrap gap-2 justify-content-md-end">
                          {% for report in school.reports %}
                            {% set is_disabled = not report.note_url %}
                            <a href="{{ report.note_url if not is_disabled else '#' }}"
                               target="_blank" rel="noopener noreferrer"
                               class="btn btn-sm {% if is_disabled %}btn-outline-secondary{% else %}btn-outline-primary{% endif %} {% if is_disabled %}disabled{% endif %}"
                               {% if is_disabled %}aria-disabled="true"{% endif %}>
                              <i class="fas fa-file-alt me-1"></i> {{ report.subject }}
                            </a>
                          {% endfor %}
                        </div>
                      </div>
                    {% else %}
                      <div class="col-12 col-md-auto">
                        <p class="card-text text-muted mb-0">この学校のレポートはまだありません。</p>
                      </div>
                    {% endif %}
                  </div>
                </div>
              </div>
            </div>
            {% endfor %}
          </div>
        {% else %}
          <div class="alert alert-info text-center">
            該当するレポートはありません。
          </div>
        {% endif %}
      </div>
    </div>
{% endblock %}

{% block scripts %}
<script>
  const schoolSearchInput = document.getElementById("schoolSearchInput");
  const subjectSelect = document.getElementById("subjectSelect");
  const schoolCountSpan = document.getElementById("schoolCount");
  const schoolsListContainer = document.getElementById("schoolsListContainer");

  // --- 関数定義 ---

  /**
   * 学校リストのHTMLを生成し、画面を更新する
   * @param {Array} schools - 表示する学校の配列
   */
  function updateSchoolList(schools) {
    schoolsListContainer.innerHTML = ''; // コンテナをクリア

    if (!schools || schools.length === 0) {
      schoolsListContainer.innerHTML = '<div class="alert alert-info text-center">該当するレポートはありません。</div>';
      schoolCountSpan.textContent = 0;
      return;
    }

    const listWrapper = document.createElement('div');
    listWrapper.className = 'row row-cols-1 g-4';
    listWrapper.id = 'schoolsList';

    schools.forEach(school => {
      const reportsHtml = school.reports.map(report => {
        const isDisabled = !report.note_url;
        const btnClass = isDisabled ? 'btn-outline-secondary disabled' : 'btn-outline-primary';
        const disabledAttrs = isDisabled ? 'aria-disabled="true"' : '';
        const href = isDisabled ? '#' : report.note_url;
        return `
          <a href="${href}" target="_blank" rel="noopener noreferrer" class="btn btn-sm ${btnClass}" ${disabledAttrs}>
            <i class="fas fa-file-alt me-1"></i> ${report.subject}
          </a>
        `;
      }).join('');

      const schoolItem = document.createElement('div');
      schoolItem.className = 'col school-item';
      schoolItem.innerHTML = `
        <div class="card shadow-sm h-100">
          <div class="card-body">
            <div class="row align-items-center g-2">
              <div class="col-12 col-md-auto flex-grow-1">
                <h5 class="card-title mb-0">${school.name}</h5>
              </div>
              <div class="col-12 col-md-auto">
                <div class="d-flex flex-wrap gap-2 justify-content-md-end">
                  ${reportsHtml}
                </div>
              </div>
            </div>
          </div>
        </div>
      `;
      listWrapper.appendChild(schoolItem);
    });

    schoolsListContainer.appendChild(listWrapper);
    schoolCountSpan.textContent = schools.length;

    // 学校名でのインクリメンタル検索を再適用
    applySchoolNameFilter();
  }

  /**
   * 学校名でのインクリメンタル検索を実行する
   */
  function applySchoolNameFilter() {
    let filter = schoolSearchInput.value.toLowerCase();
    let items = document.querySelectorAll("#schoolsList .school-item");
    let visibleCount = 0;

    items.forEach(item => {
      let title = item.querySelector(".card-title").textContent.toLowerCase().trim();
      if (title.includes(filter)) {
        item.style.display = "";
        visibleCount++;
      } else {
        item.style.display = "none";
      }
    });
    schoolCountSpan.textContent = visibleCount;
  }

  // --- イベントリスナー ---

  // 学校名検索
  schoolSearchInput.addEventListener("input", applySchoolNameFilter);

  // 教科プルダウン
  subjectSelect.addEventListener("change", function() {
    const selectedSubject = this.value;
    const apiUrl = `{{ url_for('api_schools') }}${selectedSubject ? '?subject=' + encodeURIComponent(selectedSubject) : ''}`;

    // フェッチ中にローディング表示などをしても良い
    schoolCountSpan.textContent = '検索中...';

    fetch(apiUrl)
      .then(response => response.json())
      .then(data => {
        updateSchoolList(data.schools);
      })
      .catch(error => {
        console.error('Error fetching schools:', error);
        schoolsListContainer.innerHTML = '<div class="alert alert-danger text-center">データの取得に失敗しました。</div>';
      });
  });

</script>
{% endblock %}
